contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmount) public payable {
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);

        uint balBefore = address(this).balance;
        c.deposit{value: depositAmount}();
        uint cBalBefore = address(c).balance;
        uint testBalAfterDeposit = address(this).balance;

        require(testBalAfterDeposit + depositAmount == balBefore);

        // First withdrawal
        c.withdrawAll();
        uint cBalAfterFirst = address(c).balance;
        uint testBalAfterFirst = address(this).balance;

        // Second withdrawal (should be a no-op)
        c.withdrawAll();
        uint cBalAfterSecond = address(c).balance;
        uint testBalAfterSecond = address(this).balance;

        // General rule: after a successful withdrawAll, the credit is zero,
        // c's balance decreased by exactly depositAmount, and this contract received depositAmount.
        // Also, calling withdrawAll again changes nothing.
        assert(
            cBalAfterFirst == cBalBefore - depositAmount &&
            testBalAfterFirst == testBalAfterDeposit + depositAmount &&
            cBalAfterSecond == cBalAfterFirst &&
            testBalAfterSecond == testBalAfterFirst
        );
    }

    receive() external payable {}
}

